from lib import *
S = SS('h39')
steps = [
    step("状态时间线(退避设为基础 500 ms、倍数 1.6、不抖动,用一个监视 goroutine 记录每次状态变化):NewClient 后是 IDLE;0.30 秒调用 Connect() → CONNECTING → READY(同一时刻);0.61 秒服务端 Stop → IDLE(不是 TRANSIENT_FAILURE,连接断开后客户端并不会自己重连);0.91 秒发一次调用(服务端已不在) → CONNECTING → TRANSIENT_FAILURE,调用返回 Unavailable“transport: Error while dialing: dial tcp … connect…”;服务端在 2.71 秒重新启动,状态要到 3.49 秒才回到 READY——还要等当前这一轮退避结束(与基础 0.5 秒、倍数 1.6 的退避序列 0.5、0.8、1.28 秒累加到 0.91+0.5+0.8+1.28 = 3.49 秒吻合,这是我对数字的推算)。服务端回来后的 fail-fast 调用成功。", t=tl(S(1)), done=lidx(S(1), '状态时间线(退避设为基础'), mark=lidx(S(1), '服务端重新启动'), b=bars([['服务端重新启动的时刻 s', 2.71, '2.71'], ['状态回到 READY 的时刻 s', 3.49, '3.49']], 3.6, mark=[0], done=[1]), kv=KV([['服务端 Stop', 'READY → IDLE'], ['下一次调用', 'IDLE → CONNECTING → TRANSIENT_FAILURE'], ['服务端回来后', '等退避结束才 READY(0.78 秒后)']], ['服务端回来后'])),
    step("对端接受 TCP 但不做 HTTP/2 握手(假服务端只 Accept、不回应),MinConnectTimeout = 1 秒:状态时间线是 0.00 秒 CONNECTING → 1.00 秒 TRANSIENT_FAILURE——连接建立阶段(包括等服务端前言)最多等 MinConnectTimeout,到时就当失败。TRANSIENT_FAILURE 期间发 fail-fast 调用,0.1 ms 就返回 Unavailable,“error reading server preface: read tcp …”(带着上一次失败的原因)。", t=tl(S(2)), done=lidx(S(2), '这期间发一次'), mark=lidx(S(2), '状态时间线'), b=bars([['CONNECTING → TRANSIENT_FAILURE 的时刻 s', 1.0, '1.00'], ['TRANSIENT_FAILURE 中 fail-fast 调用 ms', 0.1, '0.1']], 1.2, mark=[0], done=[1]), kv=KV([['CONNECTING', '最多 MinConnectTimeout(这里 1 秒)'], ['超时后', 'TRANSIENT_FAILURE'], ['fail-fast 调用', '立即 Unavailable']], ['CONNECTING'])),
    step("拒绝连接(端口没人监听),退避基础 500 ms、倍数 2、不抖动,观察 4 秒:状态时间线只有 0.00 秒 CONNECTING → 0.00 秒 TRANSIENT_FAILURE,之后 4 秒内一直是 TRANSIENT_FAILURE——后台虽然按退避不断重试连接,但通道状态没有再回到 CONNECTING(这个版本如此)。fail-fast 的调用 0.1 ms 就返回 Unavailable;WaitForReady(true) 且 deadline 800 ms 的调用,等满 802.1 ms 后返回 DeadlineExceeded,message 以“latest balancer error: …”开头带着最后一次连接错误。", t=tl(S(3)), done=lidx(S(3), 'WaitForReady(true)'), mark=lidx(S(3), 'fail-fast 调用'), b=bars([['fail-fast 返回 ms', 0.1, '0.1'], ['WaitForReady 返回 ms', 802.1, '802.1']], 850, mark=[0], done=[1]), kv=KV([['4 秒内的状态', '一直 TRANSIENT_FAILURE'], ['fail-fast', '立即 Unavailable'], ['WaitForReady', '等到 deadline,DeadlineExceeded']], ['4 秒内的状态'])),
    step("Close 之后:通道状态是 SHUTDOWN;再调用得到 code=Canceled,message “grpc: the client connection is closing”;WaitForReady 的调用也是同样的结果(没有任何办法让已关闭的通道再用);再 Close 一次也返回同一个错误 Canceled。收到这个错误通常说明代码里的 ClientConn 被提前关闭了(比如被 defer conn.Close() 关掉而调用还在继续)。", t=tl(S(4)), done=lidx(S(4), '再 Close 一次'), mark=lidx(S(4), 'Close 之后状态'), b=bars([['Close 之后调用成功的个数(含 WaitForReady)', 0, '0']], 1.2, done=[0]), kv=KV([['状态', 'SHUTDOWN'], ['调用', 'Canceled: the client connection is closing'], ['再 Close', '同样返回 Canceled']], ['调用'])),
    step("多个地址时通道的状态是各子连接状态的汇总:round_robin 下 2 个后端,停掉后端 1 之后调用仍成功、通道状态仍是 READY(时间线里没有任何变化);再停掉后端 2:调用 Unavailable,通道状态 TRANSIENT_FAILURE(时间线 0.50 秒 IDLE → CONNECTING → 0.51 秒 TRANSIENT_FAILURE)。pick_first 对照:停掉正在用的后端 1 → IDLE,下一次调用 → CONNECTING → 0.51 秒 READY(换到了后端 2);再停掉后端 2 → IDLE → 0.81 秒 CONNECTING → TRANSIENT_FAILURE。所以“通道 READY”只表示至少有一个子连接可用;一部分后端挂了通道状态看不出来。", t=tl(S(5)), done=lidx(S(5), '    状态时间线:0.00s CONNECTING → 0.00s READY → 0.20s'), mark=lidx(S(5), 'round_robin 停掉后端 1'), b=bars([['round_robin 停掉 1 个后端后通道状态是否仍 READY(1=是)', 1, '是'], ['两个后端都停掉后是否仍 READY', 0, 'TRANSIENT_FAILURE']], 1.2, mark=[1], done=[0]), kv=KV([['round_robin 停掉一个', '通道仍是 READY,时间线无变化'], ['两个都停掉', 'TRANSIENT_FAILURE'], ['含义', 'READY = 至少一个子连接可用']], ['含义'])),
]
A = mkarth('h39', 39, 'gRPC,连接状态,IDLE,CONNECTING,READY,TRANSIENT_FAILURE,SHUTDOWN,退避,Go,真实验证,动画演示',
    '实测 gRPC 通道状态机:断开后是 IDLE 而不是 TRANSIENT_FAILURE;服务端回来后要等当前退避结束才 READY;握手超时按 MinConnectTimeout 进入 TRANSIENT_FAILURE;拒绝连接时一直 TRANSIENT_FAILURE;Close 后是 SHUTDOWN;多地址时 READY 表示至少一个子连接可用。',
    'IDLE、CONNECTING、READY、TRANSIENT_FAILURE、SHUTDOWN 分别什么时候出现?服务端重启后客户端多久恢复?通道状态能反映后端的健康吗?这篇用一个监视 goroutine 记录每一次状态变化,画出时间线。',
    [('IDLE', '服务端断开后通道的状态(不是 TRANSIENT_FAILURE),要等下一次调用才重连'), ('2.71 秒 → 3.49 秒', '服务端重启的时刻与通道回到 READY 的时刻,中间是退避等待'), ('READY 不代表全部', 'round_robin 下停掉一个后端,通道状态仍是 READY')],
    [('五个状态', '<p>IDLE(没有连接,等调用或 Connect)、CONNECTING(建连中,包括握手)、READY(可用)、TRANSIENT_FAILURE(连接失败,退避中)、SHUTDOWN(已关闭)。</p>'),
     ('断开之后', '<p>已建立的连接断开后进入 IDLE,不会自己重连;下一次调用才触发重连,重连失败才进入 TRANSIENT_FAILURE。</p>'),
     ('退避', '<p>TRANSIENT_FAILURE 期间按退避重试,服务端恢复后要等当前退避结束才会连上。fail-fast 的调用立即失败,WaitForReady 的调用等到 deadline。</p>'),
     ('握手超时', '<p>连接建立阶段最多等 MinConnectTimeout,超时就当失败。</p>'),
     ('多个地址', '<p>通道状态是子连接状态的汇总,READY 只表示至少有一个可用,不能代替对每个后端的健康监控。</p>')],
    steps,
    [ENV_H + '。时间线由 conn.WaitForStateChange 驱动的监视 goroutine 记录(只记录状态变化,时间是相对起点的秒数);本篇把退避参数调成基础 500 ms 以便观察,默认值是基础 1 秒、倍数 1.6(第 11 篇);“假服务端”是只 Accept 不回应的 TCP 监听',
     '没有验证:IDLE 超时(WithIdleTimeout)与状态的关系(第 11 篇);其它负载均衡策略(ring_hash、least_request)的状态汇总;状态变化回调的 channelz / stats 观测方式;xDS 下的状态;TRANSIENT_FAILURE 时 round_robin 的 fail-fast 与 WaitForReady 细节;时间线中同一时刻多个状态的先后顺序是 WaitForStateChange 观察到的,可能漏掉极短暂的中间状态'],
    '通道状态')
